package com.bank.pool;

import java.util.logging.*;

public class StringPoolDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Literals are auto-interned: same pooled object.
        String a = "SAV2001";
        String b = "SAV2001";
        log.info(() -> "two literals == : " + (a == b)); // true (pooled)

        // Compile-time constant folding: "SAV" + "2001" folds to literal "SAV2001".
        String c = "SAV" + "2001";
        log.info(() -> "folded constant == literal : " + (c == a)); // true

        // Runtime concatenation with a variable: NEW, unpooled object.
        String prefix = "SAV";
        String d = prefix + "2001";
        log.info(() -> "runtime concat == literal : " + (d == a)); // false
        log.info(() -> "runtime concat .equals : " + d.equals(a)); // true

        // intern() returns the pooled reference for the value.
        String e = d.intern();
        log.info(() -> "after intern() == literal : " + (e == a)); // true

        // new String is always a distinct object.
        String f = new String("SAV2001");
        log.info(() -> "new String == literal : " + (f == a)); // false

        LabelCache cache = new LabelCache();
        String t1 = cache.normalize(new String("SAVINGS"));
        String t2 = cache.normalize(new String("SAVINGS"));
        log.info(() -> "normalized labels share object : " + (t1 == t2)); // true
    }
}

// ─── Would be LabelCache.java in a real project ───
class LabelCache {
    // Deliberately intern known, bounded label values to deduplicate memory.
    String normalize(String rawLabel) {
        return rawLabel.intern(); // reuse pooled reference for repeated labels
    }
}
